package main

import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.POST("/notes", func(c *gin.Context) {
		c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 1024)
		var in struct {
			Title string `json:"title" binding:"required,max=80"`
		}
		if err := c.ShouldBindJSON(&in); err != nil {
			var large *http.MaxBytesError
			if errors.As(err, &large) {
				c.AbortWithStatus(413)
			} else {
				c.AbortWithStatus(400)
			}
			return
		}
		title := strings.TrimSpace(in.Title)
		if title == "" {
			c.AbortWithStatus(400)
			return
		}
		c.JSON(201, gin.H{"title": title})
	})
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("POST", "/notes", strings.NewReader(`{"title":"   "}`)))
	fmt.Println(w.Code) // 400, before any write to storage
}

package main

import (
	"fmt"
	"net/http/httptest"
	"sync"

	"github.com/gin-gonic/gin"
)

type Job struct{ Path string }

func main() {
	gin.SetMode(gin.TestMode)
	jobs := make(chan Job, 1)
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		for job := range jobs {
			fmt.Println("work", job.Path)
		}
	}()
	r := gin.New()
	r.POST("/jobs", func(c *gin.Context) {
		job := Job{Path: c.Request.URL.Path}
		select {
		case jobs <- job:
			c.Status(202)
		default:
			c.Status(503)
		}
	})
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("POST", "/jobs", nil))
	fmt.Println("accepted", w.Code)
	close(jobs)
	wg.Wait()
}

