import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"

	"github.com/gin-gonic/gin"
)

// intQuery returns def when key is absent and rejects present values
// that are not integers inside [lo, hi].
func intQuery(c *gin.Context, key string, def, lo, hi int) (int, error) {
	raw, ok := c.GetQuery(key)
	if !ok {
		return def, nil
	}
	n, err := strconv.Atoi(raw)
	if err != nil || n < lo || n > hi {
		return 0, fmt.Errorf("%s must be an integer between %d and %d", key, lo, hi)
	}
	return n, nil
}

var filterKeys = map[string]bool{"status": true, "owner": true}

func search(c *gin.Context) {
	q, ok := c.GetQuery("q")
	if !ok || strings.TrimSpace(q) == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "q is required"})
		return
	}
	limit, err := intQuery(c, "limit", 20, 1, 100)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	tags := c.QueryArray("tag")
	if len(tags) > 5 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "at most 5 tag values"})
		return
	}
	filter := c.QueryMap("filter")
	for k := range filter {
		if !filterKeys[k] {
			c.JSON(http.StatusBadRequest, gin.H{"error": "unknown filter " + k})
			return
		}
	}
	c.JSON(http.StatusOK, gin.H{"q": q, "limit": limit, "tags": tags, "filter": filter})
}

func createNote(c *gin.Context) {
	title, ok := c.GetPostForm("title")
	if !ok || title == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "title is required"})
		return
	}
	priority := c.DefaultPostForm("priority", "normal")
	switch priority {
	case "low", "normal", "high":
	default:
		c.JSON(http.StatusBadRequest, gin.H{"error": "priority must be low, normal or high"})
		return
	}
	c.JSON(http.StatusCreated, gin.H{"title": title, "priority": priority})
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.GET("/search", search)
	r.POST("/notes", createNote)

	for _, target := range []string{
