package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"

	"github.com/gin-gonic/gin"
)

type user struct {
	ID    int
	First string
	Last  string
}

var users = []user{{ID: 1, First: "Test", Last: "User"}}

// requireToken stands in for real authentication: it maps a bearer token to a role.
func requireToken(c *gin.Context) {
	roles := map[string]string{"Bearer user-token": "user", "Bearer admin-token": "admin"}
	role, ok := roles[c.GetHeader("Authorization")]
	if !ok {
		c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthenticated"})
		return
	}
	c.Set("role", role)
}

func requireRole(want string) gin.HandlerFunc {
	return func(c *gin.Context) {
		if c.GetString("role") != want {
			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "forbidden"})
			return
		}
	}
}

func health(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"status": "ok"}) }

func listUsersV1(c *gin.Context) {
	out := []gin.H{}
	for _, u := range users {
		out = append(out, gin.H{"id": u.ID, "name": u.First + " " + u.Last})
	}
	c.JSON(http.StatusOK, out)
}

func listUsersV2(c *gin.Context) {
	out := []gin.H{}
	for _, u := range users {
		out = append(out, gin.H{"id": u.ID, "first_name": u.First, "last_name": u.Last})
	}
	c.JSON(http.StatusOK, gin.H{"data": out, "next_cursor": nil})
}

func getUserV1(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"id": c.Param("id")}) }

func adminStats(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"users": len(users)}) }

func newRouter() *gin.Engine {
	r := gin.New()
	r.GET("/health", health)

	api := r.Group("/api")
	v1 := api.Group("/v1", requireToken)
	v1.GET("/users", listUsersV1)
	v1.GET("/users/:id", getUserV1)
	admin := v1.Group("/admin", requireRole("admin"))
	admin.GET("/stats", adminStats)

	v2 := api.Group("/v2", requireToken)
	v2.GET("/users", listUsersV2)
	return r
}

func call(r *gin.Engine, method, path, token string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(method, path, nil)
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	return w
}

func main() {
	gin.SetMode(gin.TestMode)
	r := newRouter()

	routes := r.Routes()
	sort.Slice(routes, func(i, j int) bool { return routes[i].Path < routes[j].Path })
	public := map[string]bool{"/health": true}
	for _, rt := range routes {
		path := strings.ReplaceAll(rt.Path, ":id", "1")
		code := call(r, rt.Method, path, "").Code
		verdict := "protected"
		if code != http.StatusUnauthorized {
			verdict = "open"
			if !public[rt.Path] {
				verdict = "OPEN BY MISTAKE"
			}
		}
		fmt.Println(rt.Method, rt.Path, rt.Handler, code, verdict)
	}

	fmt.Println("v1", call(r, http.MethodGet, "/api/v1/users", "user-token").Body.String())
	fmt.Println("v2", call(r, http.MethodGet, "/api/v2/users", "user-token").Body.String())
	fmt.Println("admin as user", call(r, http.MethodGet, "/api/v1/admin/stats", "user-token").Code)
	fmt.Println("admin as admin", call(r, http.MethodGet, "/api/v1/admin/stats", "admin-token").Body.String())
}

package main

import (
	"fmt"
	"math"
	"net/http"
	"net/http/httptest"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

// account is the storage model. It is never rendered directly.
type account struct {
	ID           int64
	Email        string
	PasswordHash string
	CreatedAt    time.Time
	UpdatedAt    time.Time
	DeletedAt    time.Time
}

// accountResponse is the public contract for GET /accounts/:id.
type accountResponse struct {
	ID        int64     `json:"id"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at,omitempty"` // omitempty never omits a struct
	DeletedAt time.Time `json:"deleted_at,omitzero"`  // omitzero uses time.Time.IsZero
}

func toResponse(a account) accountResponse {
	return accountResponse{ID: a.ID, Email: a.Email, CreatedAt: a.CreatedAt, UpdatedAt: a.UpdatedAt, DeletedAt: a.DeletedAt}
}

func main() {
	gin.SetMode(gin.TestMode)
	acct := account{
		ID:           7,
		Email:        "dev@example.com",
		PasswordHash: "$2a$10$not-a-real-hash",
		CreatedAt:    time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC),
	}
	text := gin.H{"note": "<b>R&D</b> café"}

	var lastErr string
	r := gin.New()
	r.Use(func(c *gin.Context) {
		c.Next()
		if len(c.Errors) > 0 {
			lastErr = c.Errors.Last().Error()
		}
	})
	r.GET("/json", func(c *gin.Context) { c.JSON(http.StatusOK, text) })
	r.GET("/pure", func(c *gin.Context) { c.PureJSON(http.StatusOK, text) })
	r.GET("/ascii", func(c *gin.Context) { c.AsciiJSON(http.StatusOK, text) })
	r.GET("/indented", func(c *gin.Context) { c.IndentedJSON(http.StatusOK, gin.H{"ok": true}) })
	r.GET("/secure-list", func(c *gin.Context) { c.SecureJSON(http.StatusOK, []int{1, 2}) })
	r.GET("/secure-object", func(c *gin.Context) { c.SecureJSON(http.StatusOK, gin.H{"ok": true}) })
	r.GET("/leaky", func(c *gin.Context) { c.JSON(http.StatusOK, acct) })
	r.GET("/accounts/7", func(c *gin.Context) { c.JSON(http.StatusOK, toResponse(acct)) })
	r.GET("/no-content", func(c *gin.Context) { c.JSON(http.StatusNoContent, gin.H{"dropped": true}) })
	r.GET("/nan", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"ratio": math.NaN()}) })

	for _, path := range []string{
		"/json", "/pure", "/ascii", "/indented", "/secure-list", "/secure-object",
		"/leaky", "/accounts/7", "/no-content", "/nan",
	} {
		lastErr = ""
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, path, nil))
		body := strings.ReplaceAll(w.Body.String(), "\n", `\n`)
		if body == "" {
			body = "(empty body)"
		}
		fmt.Printf("%s %d [%s] %s\n", path, w.Code, w.Header().Get("Content-Type"), body)
		if lastErr != "" {
			fmt.Println("  c.Errors:", lastErr)
		}
	}
}

type page struct {
	Items      []item    `json:"items"`                 // nil renders null: initialize to []item{}
	NextCursor string    `json:"next_cursor,omitempty"` // omitted on the last page
	Total      int       `json:"total,omitzero"`        // omitted when 0: is 0 a real answer?
	Generated  time.Time `json:"generated_at,omitzero"` // omitted when IsZero reports true
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

// One small struct per source: each binder validates the whole struct it fills.
type projectURI struct {
	Project string `uri:"project" binding:"required,alphanum,max=32"`
}

type listQuery struct {
	Limit int    `form:"limit,default=20" binding:"min=1,max=100"`
	Sort  string `form:"sort,default=created" binding:"oneof=created title"`
}

type traceHeader struct {
	RequestID string `header:"X-Request-Id"`
}

type noteURI struct {
	ID int64 `uri:"id" binding:"required,min=1"`
}

type patchHeader struct {
	IfMatch string `header:"If-Match" binding:"required"`
}

type patchBody struct {
	Title string `json:"title" binding:"required,max=80"`
}

type createNote struct {
	Title string `json:"title" form:"title" binding:"required,max=80"`
}

type envelope struct {
	Type string `json:"type" binding:"required"`
}

type noteCreated struct {
	Data struct {
		ID    int64  `json:"id" binding:"required"`
		Title string `json:"title" binding:"required"`
	} `json:"data"`
}

func bad(c *gin.Context, source string) {
	c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "invalid " + source})
}

func listNotes(c *gin.Context) {
	var uri projectURI
	var q listQuery
	var h traceHeader
	if c.ShouldBindUri(&uri) != nil {
		bad(c, "path")
		return
	}
	if c.ShouldBindQuery(&q) != nil {
		bad(c, "query")
		return
	}
	if c.ShouldBindHeader(&h) != nil {
		bad(c, "headers")
		return
	}
	c.JSON(http.StatusOK, gin.H{"project": uri.Project, "limit": q.Limit, "sort": q.Sort, "request_id": h.RequestID})
}

func patchNote(c *gin.Context) {
	var uri noteURI
	var h patchHeader
	var body patchBody
	if c.ShouldBindUri(&uri) != nil {
		bad(c, "path")
		return
	}
	if c.ShouldBindHeader(&h) != nil {
		bad(c, "headers")
		return
	}
	if c.ShouldBindJSON(&body) != nil {
		bad(c, "body")
		return
	}
	c.JSON(http.StatusOK, gin.H{"id": uri.ID, "if_match": h.IfMatch, "title": body.Title})
}

func postNote(c *gin.Context) {
	var in createNote
	if err := c.ShouldBind(&in); err != nil {
		bad(c, "body")
		return
	}
	c.JSON(http.StatusCreated, gin.H{"title": in.Title, "via": c.ContentType()})
}

func webhook(c *gin.Context) {
	var env envelope
	if c.ShouldBindBodyWithJSON(&env) != nil {
		bad(c, "envelope")
		return
	}
	switch env.Type {
	case "note.created":
		var ev noteCreated
		if c.ShouldBindBodyWithJSON(&ev) != nil {
			bad(c, "note.created payload")
			return
		}
		c.JSON(http.StatusAccepted, gin.H{"handled": env.Type, "id": ev.Data.ID})
	default:
		c.JSON(http.StatusAccepted, gin.H{"ignored": env.Type})
	}
}

func webhookNaive(c *gin.Context) {
	var env envelope
	var ev noteCreated
	_ = c.ShouldBindJSON(&env)
	if err := c.ShouldBindJSON(&ev); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"second_read": err.Error()})
		return
	}
	c.Status(http.StatusAccepted)
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.GET("/projects/:project/notes", listNotes)
	r.PATCH("/notes/:id", patchNote)
	r.POST("/notes", postNote)
	r.POST("/webhooks", webhook)
	r.POST("/webhooks-naive", webhookNaive)

	const event = `{"type":"note.created","data":{"id":9,"title":"Hi"}}`
	cases := []struct {
		method, target, contentType, body string
		headers                           map[string]string
	}{
		{"GET", "/projects/core/notes", "", "", nil},
		{"GET", "/projects/core/notes?limit=0", "", "", nil},
		{"GET", "/projects/core/notes?limit=5&sort=title", "", "", map[string]string{"X-Request-Id": "r-42"}},
		{"GET", "/projects/core.v2/notes", "", "", nil},
		{"PATCH", "/notes/abc", "application/json", `{"title":"Renamed"}`, nil},
		{"PATCH", "/notes/7", "application/json", `{"title":"Renamed"}`, nil},
