import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

type Article struct {
	ID      int       `json:"id"`
	Title   string    `json:"title"`
	Updated time.Time `json:"updated"`
}

// strongETag names these exact bytes: any change in the body changes it.
func strongETag(body []byte) string {
	sum := sha256.Sum256(body)
	return `"` + hex.EncodeToString(sum[:12]) + `"`
}

// matches applies the weak comparison RFC 9110 requires for If-None-Match.
func matches(ifNoneMatch, etag string) bool {
	if strings.TrimSpace(ifNoneMatch) == "*" {
		return true
	}
	for candidate := range strings.SplitSeq(ifNoneMatch, ",") {
		if strings.TrimPrefix(strings.TrimSpace(candidate), "W/") == etag {
			return true
		}
	}
	return false
}

func notModified(c *gin.Context, etag string, modified time.Time) bool {
	if inm := c.GetHeader("If-None-Match"); inm != "" {
		return matches(inm, etag) // when present, If-Modified-Since is ignored
	}
	since, err := http.ParseTime(c.GetHeader("If-Modified-Since"))
	return err == nil && !modified.Truncate(time.Second).After(since)
}

// serve renders v once, then answers 200 with the bytes or 304 without them.
func serve(c *gin.Context, cacheControl string, modified time.Time, v any) {
	body, err := json.Marshal(v)
	if err != nil {
		c.AbortWithStatus(http.StatusInternalServerError)
		return
	}
	etag := strongETag(body)
	c.Header("ETag", etag)
	c.Header("Cache-Control", cacheControl)
	if !modified.IsZero() {
		c.Header("Last-Modified", modified.UTC().Format(http.TimeFormat))
	}
	if notModified(c, etag, modified) {
		c.Status(http.StatusNotModified) // same validators and caching headers, no body
		return
	}
	c.Data(http.StatusOK, "application/json; charset=utf-8", body)
}

func main() {
	gin.SetMode(gin.TestMode)
	article := Article{ID: 7, Title: "Draining HTTP servers", Updated: time.Date(2026, 11, 2, 9, 30, 0, 0, time.UTC)}

	r := gin.New()
	r.GET("/articles/:id", func(c *gin.Context) {
		serve(c, "public, max-age=60", article.Updated, article)
	})
	r.GET("/me", func(c *gin.Context) {
		if c.GetHeader("Authorization") != "Bearer t-user-17" {
			c.AbortWithStatus(http.StatusUnauthorized)
			return
		}
		c.Header("Vary", "Authorization")
		serve(c, "private, no-cache", time.Time{}, gin.H{"user": "user-17", "plan": "team"})
	})

	get := func(label, path string, headers ...string) *httptest.ResponseRecorder {
		req := httptest.NewRequest("GET", path, nil)
		for i := 0; i+1 < len(headers); i += 2 {
			req.Header.Set(headers[i], headers[i+1])
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Printf("%s: %d etag=%s cache=%q bytes=%d\n", label, w.Code,
			w.Header().Get("ETag"), w.Header().Get("Cache-Control"), w.Body.Len())
		return w
	}

	first := get("first fetch", "/articles/7")
	etag, lastModified := first.Header().Get("ETag"), first.Header().Get("Last-Modified")
	fmt.Println("  Last-Modified:", lastModified)
	get("If-None-Match", "/articles/7", "If-None-Match", etag)
	get("weak If-None-Match", "/articles/7", "If-None-Match", "W/"+etag)
	get("If-Modified-Since", "/articles/7", "If-Modified-Since", lastModified)

	// An edit 400ms later: same second, so Last-Modified cannot see it.
	article.Title = "Draining HTTP servers safely"
	article.Updated = article.Updated.Add(400 * time.Millisecond)
	get("edited, If-Modified-Since", "/articles/7", "If-Modified-Since", lastModified)
	get("edited, If-None-Match", "/articles/7", "If-None-Match", etag)
	get("private data", "/me", "Authorization", "Bearer t-user-17")
}

