// ---- internal/notes: the domain. Imports only the standard library. ----

type Note struct {
	ID    string `json:"id"`
	Title string `json:"title"`
}

var (
	ErrNotFound = errors.New("notes: not found")
	ErrInvalid  = errors.New("notes: invalid input")
)

// Store is what the service needs from persistence; adapters implement it.
type Store interface {
	Insert(ctx context.Context, n Note) error
	Get(ctx context.Context, id string) (Note, error)
}

type Service struct {
	store  Store
	nextID func() string
}

func NewService(store Store, nextID func() string) *Service {
	return &Service{store: store, nextID: nextID}
}

func (s *Service) Create(ctx context.Context, title string) (Note, error) {
	title = strings.TrimSpace(title)
	if title == "" || len(title) > 80 {
		return Note{}, ErrInvalid
	}
	n := Note{ID: s.nextID(), Title: title}
	return n, s.store.Insert(ctx, n)
}

func (s *Service) Get(ctx context.Context, id string) (Note, error) {
	return s.store.Get(ctx, id)
}

// ---- internal/store: an adapter. Imports notes, never httpapi. ----

type MemoryStore struct {
	mu    sync.RWMutex
	notes map[string]Note
}

func NewMemoryStore() *MemoryStore {
	return &MemoryStore{notes: map[string]Note{}}
}

func (m *MemoryStore) Insert(_ context.Context, n Note) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.notes[n.ID] = n
	return nil
}

func (m *MemoryStore) Get(_ context.Context, id string) (Note, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	n, ok := m.notes[id]
	if !ok {
		return Note{}, ErrNotFound
	}
	return n, nil
}

// ---- internal/httpapi: the Gin adapter. Imports notes, never store. ----

type NoteService interface {
	Create(ctx context.Context, title string) (Note, error)
	Get(ctx context.Context, id string) (Note, error)
}

type Handler struct{ svc NoteService }

func NewRouter(h *Handler) *gin.Engine {
	r := gin.New()
	r.Use(gin.Recovery())
	r.POST("/notes", h.create)
	r.GET("/notes/:id", h.get)
	return r
}

func (h *Handler) create(c *gin.Context) {
	var in struct {
		Title string `json:"title"`
	}
	if err := c.ShouldBindJSON(&in); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "malformed body"})
		return
	}
	n, err := h.svc.Create(c.Request.Context(), in.Title)
	if err != nil {
		writeError(c, err)
		return
	}
	c.JSON(http.StatusCreated, n)
}

func (h *Handler) get(c *gin.Context) {
	n, err := h.svc.Get(c.Request.Context(), c.Param("id"))
	if err != nil {
		writeError(c, err)
		return
	}
	c.JSON(http.StatusOK, n)
}

func writeError(c *gin.Context, err error) {
	switch {
	case errors.Is(err, ErrNotFound):
		c.JSON(http.StatusNotFound, gin.H{"error": "note not found"})
	case errors.Is(err, ErrInvalid):
		c.JSON(http.StatusUnprocessableEntity, gin.H{"error": "title must be 1-80 characters"})
	default:
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
	}
}

// ---- cmd/api: the composition root. The only place that knows every concrete type. ----

func main() {
	gin.SetMode(gin.TestMode)

	seq := 0
	nextID := func() string { seq++; return fmt.Sprintf("n%d", seq) }

	store := NewMemoryStore()
	svc := NewService(store, nextID)
