		req := httptest.NewRequest(rq.method, rq.path, strings.NewReader(rq.body))
		req.Header.Set("Content-Type", "application/json")
		router.ServeHTTP(w, req)
		fmt.Println(rq.method, rq.path, w.Code, w.Body.String())
	}
}

