		return nil, errors.New("notes: NewService needs a store, a clock and an ID source")
	}
	return &Service{store: store, now: now, nextID: nextID}, nil
}

func (s *Service) Create(ctx context.Context, title string) (Note, error) {
	n := Note{ID: s.nextID(), Title: strings.TrimSpace(title), CreatedAt: s.now().UTC()}
