	send(r, http.MethodGet, "/notes/n7", "")
	send(r, http.MethodPost, "/notes", `{"title":"Review PR"}`)
	fmt.Println("store calls:", healthy.calls)

	broken := &fakeStore{err: errors.New("dial tcp 192.0.2.10:5432: connection refused")}
	r, err = newTestRouter(broken, log)
	if err != nil {
		panic(err)
	}
	send(r, http.MethodGet, "/notes/n7", "")
}

