package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"

	"github.com/gin-gonic/gin"
)

// ---- internal/notes ----

type Note struct {
	ID     string `json:"id"`
	Title  string `json:"title"`
	Body   string `json:"body"`
	Pinned bool   `json:"pinned"`
}

var (
	ErrNotFound = errors.New("notes: not found")
	ErrConflict = errors.New("notes: title already used")
)

type Store interface {
	Create(ctx context.Context, n Note) error
	Get(ctx context.Context, id string) (Note, error)
	// Update runs fn on a copy under the store's lock and saves the result.
	Update(ctx context.Context, id string, fn func(*Note) error) (Note, error)
	Delete(ctx context.Context, id string) error
}

// ---- internal/store ----

type MemoryStore struct {
	mu      sync.RWMutex
	byID    map[string]Note
	byTitle map[string]string // unique index: title -> id
}

func NewMemoryStore() *MemoryStore {
	return &MemoryStore{byID: map[string]Note{}, byTitle: map[string]string{}}
}

func (m *MemoryStore) Create(_ context.Context, n Note) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, taken := m.byTitle[n.Title]; taken {
		return ErrConflict
	}
	m.byID[n.ID] = n
	m.byTitle[n.Title] = n.ID
	return nil
}

func (m *MemoryStore) Get(_ context.Context, id string) (Note, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	n, ok := m.byID[id]
	if !ok {
		return Note{}, ErrNotFound
	}
	return n, nil // a copy: callers cannot mutate the map behind the lock
}

func (m *MemoryStore) Update(_ context.Context, id string, fn func(*Note) error) (Note, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	old, ok := m.byID[id]
	if !ok {
		return Note{}, ErrNotFound
	}
	next := old
	if err := fn(&next); err != nil {
		return Note{}, err
	}
	next.ID = old.ID // the URL owns the identity, not the body
	if owner, taken := m.byTitle[next.Title]; taken && owner != id {
		return Note{}, ErrConflict
	}
	delete(m.byTitle, old.Title)
	m.byTitle[next.Title] = id
	m.byID[id] = next
	return next, nil
}

func (m *MemoryStore) Delete(_ context.Context, id string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	n, ok := m.byID[id]
	if !ok {
		return ErrNotFound
	}
	delete(m.byTitle, n.Title)
	delete(m.byID, id)
	return nil
}

// ---- internal/httpapi ----

type Handler struct {
	store  Store
	nextID func() string
}

func (h *Handler) Register(r gin.IRouter) {
	r.POST("/notes", h.create)
	r.GET("/notes/:id", h.get)
	r.PUT("/notes/:id", h.replace)
	r.PATCH("/notes/:id", h.patch)
	r.DELETE("/notes/:id", h.remove)
}

// putNote is a full representation: an absent field means its zero value.
type putNote struct {
	Title  string `json:"title" binding:"required,max=80"`
	Body   string `json:"body" binding:"max=2000"`
	Pinned bool   `json:"pinned"`
}

// patchNote uses pointers: nil means "not sent", so false and "" stay expressible.
type patchNote struct {
	Title  *string `json:"title" binding:"omitempty,min=1,max=80"`
	Body   *string `json:"body" binding:"omitempty,max=2000"`
	Pinned *bool   `json:"pinned"`
}

func (h *Handler) create(c *gin.Context) {
	var in putNote
	if err := c.ShouldBindJSON(&in); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid note"})
		return
	}
	n := Note{ID: h.nextID(), Title: in.Title, Body: in.Body, Pinned: in.Pinned}
	if err := h.store.Create(c.Request.Context(), n); err != nil {
		writeError(c, err)
		return
	}
	c.Header("Location", "/notes/"+n.ID)
	c.JSON(http.StatusCreated, n)
}

func (h *Handler) get(c *gin.Context) {
	n, err := h.store.Get(c.Request.Context(), c.Param("id"))
	if err != nil {
		writeError(c, err)
		return
	}
	c.JSON(http.StatusOK, n)
}

func (h *Handler) replace(c *gin.Context) {
	var in putNote
	if err := c.ShouldBindJSON(&in); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid note"})
		return
	}
	n, err := h.store.Update(c.Request.Context(), c.Param("id"), func(n *Note) error {
		n.Title, n.Body, n.Pinned = in.Title, in.Body, in.Pinned
		return nil
	})
	if err != nil {
		writeError(c, err)
		return
	}
	c.JSON(http.StatusOK, n)
}

func (h *Handler) patch(c *gin.Context) {
	var in patchNote
	if err := c.ShouldBindJSON(&in); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid patch"})
		return
	}
	n, err := h.store.Update(c.Request.Context(), c.Param("id"), func(n *Note) error {
		if in.Title != nil {
			n.Title = *in.Title
		}
		if in.Body != nil {
			n.Body = *in.Body
		}
		if in.Pinned != nil {
			n.Pinned = *in.Pinned
		}
		return nil
	})
	if err != nil {
		writeError(c, err)
		return
	}
	c.JSON(http.StatusOK, n)
}

func (h *Handler) remove(c *gin.Context) {
	if err := h.store.Delete(c.Request.Context(), c.Param("id")); err != nil {
		writeError(c, err)
		return
	}
	c.Status(http.StatusNoContent)
}

// writeError is a stopgap; the problem-details lesson moves this into one middleware.
func writeError(c *gin.Context, err error) {
	switch {
	case errors.Is(err, ErrNotFound):
		c.JSON(http.StatusNotFound, gin.H{"error": "note not found"})
	case errors.Is(err, ErrConflict):
		c.JSON(http.StatusConflict, gin.H{"error": "title already used"})
	default:
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	seq := 0
	h := &Handler{store: NewMemoryStore(), nextID: func() string { seq++; return fmt.Sprintf("n%d", seq) }}
	r := gin.New()
	h.Register(r)

	steps := []struct{ method, path, body string }{
		{"POST", "/notes", `{"title":"Groceries","body":"milk, eggs"}`},
		{"POST", "/notes", `{"title":"Groceries"}`},
		{"PATCH", "/notes/n1", `{"pinned":true}`},
		{"PUT", "/notes/n1", `{"title":"Groceries"}`},
		{"POST", "/notes", `{"title":"Errands"}`},
		{"PATCH", "/notes/n3", `{"title":""}`},
		{"PATCH", "/notes/n3", `{"title":"Groceries"}`},
		{"DELETE", "/notes/n1", ""},
		{"GET", "/notes/n1", ""},
	}
	for _, s := range steps {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(s.method, s.path, strings.NewReader(s.body)))
		line := fmt.Sprintf("%s %s -> %d", s.method, s.path, w.Code)
		if loc := w.Header().Get("Location"); loc != "" {
			line += " Location: " + loc
		}
		if w.Body.Len() > 0 {
			line += " " + w.Body.String()
		}
		fmt.Println(line)
	}
}

package main

import (
	"cmp"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"maps"
	"net/http"
	"net/http/httptest"
	"net/url"
	"slices"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

type Note struct {
	ID        string    `json:"id"`
	Title     string    `json:"title"`
	Pinned    bool      `json:"pinned"`
	CreatedAt time.Time `json:"createdAt"`
}

const (
	defaultLimit = 20
	maxLimit     = 100
)

// The sort allow-list: public name -> direction and key. Nothing else is accepted.
type sortSpec struct {
	desc bool
	key  func(Note) string
}

func createdKey(n Note) string {
	// Fixed width, UTC, microseconds: compares correctly as a string.
	return n.CreatedAt.UTC().Format("2006-01-02T15:04:05.000000Z")
}

var sorts = map[string]sortSpec{
	"created":  {desc: false, key: createdKey},
	"-created": {desc: true, key: createdKey},
	"title":    {desc: false, key: func(n Note) string { return n.Title }},
}

type cursor struct {
	Sort string `json:"s"`
	Key  string `json:"k"`
	ID   string `json:"id"`
}

func encodeCursor(c cursor) string {
	b, _ := json.Marshal(c)
	return base64.RawURLEncoding.EncodeToString(b)
}

func decodeCursor(s string) (cursor, error) {
	var c cursor
	b, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil || json.Unmarshal(b, &c) != nil || c.ID == "" {
		return cursor{}, errors.New("cursor is invalid")
	}
	return c, nil
}

// compare orders by (key, id); the id tie-breaker makes the order total.
func compare(s sortSpec, aKey, aID, bKey, bID string) int {
	c := cmp.Or(cmp.Compare(aKey, bKey), cmp.Compare(aID, bID))
	if s.desc {
		return -c
	}
	return c
}

type listQuery struct {
	limit  int
	sort   string
	pinned *bool
	after  *cursor
}

func parseList(rawQuery string) (listQuery, error) {
	q, err := url.ParseQuery(rawQuery)
	if err != nil {
		return listQuery{}, errors.New("query string is malformed")
	}
	allowed := map[string]bool{"limit": true, "cursor": true, "sort": true, "pinned": true}
	for _, k := range slices.Sorted(maps.Keys(q)) {
		if !allowed[k] {
			return listQuery{}, fmt.Errorf("unknown query parameter: %s", k)
		}
	}
	lq := listQuery{limit: defaultLimit, sort: "-created"}
	if v := q.Get("limit"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 {
			return listQuery{}, errors.New("limit must be a positive integer")
		}
		lq.limit = min(n, maxLimit)
	}
	if v := q.Get("sort"); v != "" {
		if _, ok := sorts[v]; !ok {
			names := slices.Sorted(maps.Keys(sorts))
			return listQuery{}, fmt.Errorf("sort must be one of %s", strings.Join(names, ", "))
		}
		lq.sort = v
	}
	if v := q.Get("pinned"); v != "" {
		b, err := strconv.ParseBool(v)
		if err != nil {
			return listQuery{}, errors.New("pinned must be true or false")
		}
		lq.pinned = &b
	}
	if v := q.Get("cursor"); v != "" {
		c, err := decodeCursor(v)
		if err != nil {
			return listQuery{}, err
		}
		if q.Get("sort") != "" && c.Sort != lq.sort {
			return listQuery{}, errors.New("cursor was issued for a different sort")
		}
		lq.sort, lq.after = c.Sort, &c
	}
	return lq, nil
}

type MemoryStore struct {
	mu    sync.RWMutex
	notes []Note
}

func (m *MemoryStore) Add(n Note) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.notes = append(m.notes, n)
}

// List returns one page and the cursor for the next one ("" when there is none).
func (m *MemoryStore) List(q listQuery) ([]Note, string) {
	m.mu.RLock()
	all := slices.Clone(m.notes)
	m.mu.RUnlock()

	spec := sorts[q.sort]
	slices.SortFunc(all, func(a, b Note) int {
		return compare(spec, spec.key(a), a.ID, spec.key(b), b.ID)
	})
	page := make([]Note, 0, q.limit+1)
	for _, n := range all {
		if q.pinned != nil && n.Pinned != *q.pinned {
			continue
		}
		if q.after != nil && compare(spec, spec.key(n), n.ID, q.after.Key, q.after.ID) <= 0 {
			continue
		}
		page = append(page, n)
		if len(page) == q.limit+1 { // one extra row tells us a next page exists
			break
		}
	}
	if len(page) <= q.limit {
		return page, ""
	}
	page = page[:q.limit]
	last := page[len(page)-1]
	return page, encodeCursor(cursor{Sort: q.sort, Key: spec.key(last), ID: last.ID})
}

type pageBody struct {
	Items      []Note `json:"items"`
	Limit      int    `json:"limit"`
	NextCursor string `json:"nextCursor,omitempty"`
}

func newRouter(st *MemoryStore) *gin.Engine {
	r := gin.New()
	r.GET("/notes", func(c *gin.Context) {
		q, err := parseList(c.Request.URL.RawQuery)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		items, next := st.List(q)
		c.JSON(http.StatusOK, pageBody{Items: items, Limit: q.limit, NextCursor: next})
	})
	return r
}

func at(min int) time.Time { return time.Date(2026, 3, 1, 9, min, 0, 0, time.UTC) }

func seed() *MemoryStore {
	st := &MemoryStore{}
	st.Add(Note{ID: "n1", Title: "Alpha", Pinned: true, CreatedAt: at(0)})
	st.Add(Note{ID: "n2", Title: "Bravo", CreatedAt: at(5)})
	st.Add(Note{ID: "n3", Title: "Charlie", CreatedAt: at(5)}) // same instant as n2
	st.Add(Note{ID: "n4", Title: "Delta", Pinned: true, CreatedAt: at(10)})
	st.Add(Note{ID: "n5", Title: "Echo", CreatedAt: at(15)})
	return st
}

func get(r http.Handler, target string) (int, pageBody, string) {
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, target, nil))
	var p pageBody
	_ = json.Unmarshal(w.Body.Bytes(), &p)
	return w.Code, p, w.Body.String()
}

func ids(ns []Note) string {
	out := make([]string, len(ns))
	for i, n := range ns {
		out[i] = n.ID
	}
	return "[" + strings.Join(out, " ") + "]"
}

func main() {
	gin.SetMode(gin.TestMode)

	// Offset pagination: a write between two page requests shifts every row.
	st := seed()
	q := listQuery{limit: 100, sort: "-created"}
	all, _ := st.List(q)
	page1 := all[0:2]
	st.Add(Note{ID: "n6", Title: "Foxtrot", CreatedAt: at(20)})
	all, _ = st.List(q)
	fmt.Println("offset:", ids(page1), "then", ids(all[2:4]))

	// Cursor pagination: the next page starts after the last key, not at a row count.
	st = seed()
	r := newRouter(st)
	_, p, _ := get(r, "/notes?limit=2")
	fmt.Println("cursor page 1:", ids(p.Items))
	raw, _ := base64.RawURLEncoding.DecodeString(p.NextCursor)
	fmt.Println("cursor decodes to", string(raw))
	st.Add(Note{ID: "n6", Title: "Foxtrot", CreatedAt: at(20)})
	for page := 2; p.NextCursor != ""; page++ {
		_, p, _ = get(r, "/notes?limit=2&cursor="+p.NextCursor)
		fmt.Printf("cursor page %d: %s more=%t\n", page, ids(p.Items), p.NextCursor != "")
	}

	_, p, _ = get(r, "/notes?pinned=true&sort=title")
	fmt.Println("pinned by title:", ids(p.Items))
	_, p, _ = get(r, "/notes?limit=500")
	fmt.Println("limit=500 ->", p.Limit)
	for _, target := range []string{"/notes?sort=password", "/notes?pined=true", "/notes?sort=title;DROP"} {
		code, _, body := get(r, target)
		fmt.Println(target, code, body)
	}
}

// Public sort name -> constant SQL. Client input selects a key; it never becomes SQL text.
var orderBy = map[string]string{
	"created":  "created_at ASC, id ASC",
	"-created": "created_at DESC, id DESC",
	"title":    "title ASC, id ASC",
}

var afterCursor = map[string]string{
	"created":  "(created_at, id) > ($2, $3)",
	"-created": "(created_at, id) < ($2, $3)",
	"title":    "(title, id) > ($2, $3)",
}

// listSQL assumes q came from parseList, so q.sort is a key of orderBy.
func listSQL(ownerID string, q listQuery) (string, []any) {
	query := "SELECT id, title, pinned, created_at FROM notes WHERE owner_id = $1"
	args := []any{ownerID}
	if q.after != nil {
		query += " AND " + afterCursor[q.sort]
		args = append(args, q.after.Key, q.after.ID)
	}
	if q.pinned != nil {
		args = append(args, *q.pinned)
		query += fmt.Sprintf(" AND pinned = $%d", len(args))
	}
	args = append(args, q.limit+1) // one extra row reveals whether a next page exists
	query += fmt.Sprintf(" ORDER BY %s LIMIT $%d", orderBy[q.sort], len(args))
	return query, args
}

package main

import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

// ---- internal/notes: the error taxonomy. No HTTP here. ----

var (
	ErrNotFound  = errors.New("notes: not found")
	ErrConflict  = errors.New("notes: conflicts with current state")
	ErrForbidden = errors.New("notes: caller may not do this")
)

type FieldError struct {
	Field  string `json:"field"`
	Reason string `json:"reason"`
}

// ValidationError carries messages written for clients; it is safe to expose.
type ValidationError struct{ Fields []FieldError }

func (e *ValidationError) Error() string {
	return fmt.Sprintf("notes: %d invalid fields", len(e.Fields))
}

// ---- internal/httpapi: the one place that maps errors to HTTP. ----

var errMalformedBody = errors.New("httpapi: malformed body")

type Problem struct {
	Type     string       `json:"type"`
	Title    string       `json:"title"`
	Status   int          `json:"status"`
	Detail   string       `json:"detail,omitempty"`
	Instance string       `json:"instance,omitempty"`
	Errors   []FieldError `json:"errors,omitempty"`
}

const typeBase = "https://example.com/problems/"

func problemFor(err error) Problem {
	if ve, ok := errors.AsType[*ValidationError](err); ok {
		return Problem{Type: typeBase + "validation", Title: "Invalid note", Status: http.StatusUnprocessableEntity,
			Detail: "One or more fields are invalid.", Errors: ve.Fields}
	}
	switch {
	case errors.Is(err, errMalformedBody):
		return Problem{Type: typeBase + "malformed-body", Title: "Malformed request body", Status: http.StatusBadRequest}
	case errors.Is(err, ErrNotFound):
		return Problem{Type: typeBase + "not-found", Title: "Note not found", Status: http.StatusNotFound}
	case errors.Is(err, ErrConflict):
		return Problem{Type: typeBase + "conflict", Title: "Note conflicts with current state", Status: http.StatusConflict,
			Detail: "Another note already uses this title."}
	case errors.Is(err, ErrForbidden):
		return Problem{Type: typeBase + "forbidden", Title: "Action not allowed", Status: http.StatusForbidden}
	}
	return Problem{Type: "about:blank", Title: "Internal Server Error", Status: http.StatusInternalServerError}
}

func problems(logf func(format string, args ...any)) gin.HandlerFunc {
	return func(c *gin.Context) {
		c.Next()
		if len(c.Errors) == 0 {
			return
		}
		err := c.Errors.Last().Err
		p := problemFor(err)
		if p.Status >= http.StatusInternalServerError {
			logf("%s %s: %v", c.Request.Method, c.Request.URL.Path, err) // full cause, server side only
		}
		if c.Writer.Written() {
			return // a handler already committed a response; never write a second one
		}
		p.Instance = c.Request.URL.Path
		c.Header("Content-Type", "application/problem+json")
		c.JSON(p.Status, p)
	}
}

// Handlers record the cause and return. They never choose a status for an error.

func getNote(c *gin.Context) {
	_ = c.Error(fmt.Errorf("load note %s: %w", c.Param("id"), ErrNotFound))
}

func createNote(c *gin.Context) {
	var in struct {
		Title *string `json:"title"`
	}
	if err := c.ShouldBindJSON(&in); err != nil {
		_ = c.Error(fmt.Errorf("%w: %v", errMalformedBody, err))
		return
	}
	if in.Title == nil || strings.TrimSpace(*in.Title) == "" {
		_ = c.Error(&ValidationError{Fields: []FieldError{{Field: "title", Reason: "must not be blank"}}})
		return
	}
	_ = c.Error(fmt.Errorf("insert note: %w", ErrConflict))
}

func deleteNote(c *gin.Context) {
	_ = c.Error(fmt.Errorf("delete note %s owned by u2: %w", c.Param("id"), ErrForbidden))
}

func exportNotes(c *gin.Context) {
	_ = c.Error(errors.New(`pq: password authentication failed for user "notes_rw" at 192.0.2.10:5432`))
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.Use(problems(func(format string, args ...any) { fmt.Printf("log: "+format+"\n", args...) }))
	r.NoRoute(func(c *gin.Context) { _ = c.Error(ErrNotFound) })
	r.GET("/notes/:id", getNote)
	r.POST("/notes", createNote)
	r.DELETE("/notes/:id", deleteNote)
	r.GET("/export", exportNotes)

	requests := []struct{ method, path, body string }{
		{"GET", "/notes/n9", ""},
		{"POST", "/notes", `{"title":`},
		{"POST", "/notes", `{"title":"  "}`},
		{"POST", "/notes", `{"title":"Groceries"}`},
		{"DELETE", "/notes/n1", ""},
		{"GET", "/export", ""},
		{"GET", "/nowhere", ""},
	}
	for _, rq := range requests {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(rq.method, rq.path, strings.NewReader(rq.body)))
		fmt.Println(w.Code, w.Header().Get("Content-Type"), w.Body.String())
	}
}

